def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split path into components
    if path.startswith('/'):
        components = path[1:].split('/')
    else:
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        # Check if this is a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            # Resolve remaining components after this link
            remaining = components[i+1:]

            # Process the symlink target
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Target is relative to the directory containing the link
                if next_path == '/':
                    current = '/'
                else:
                    current = next_path.rsplit('/', 1)[0]
                target_components = target.split('/')

            # Prepend target components to remaining components
            components = target_components + remaining
            i = 0
            continue

        # Not a symlink, just update current path
        current = next_path
        i += 1

    # Remove trailing slash except for root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

